update public.learning_paths
set
  title = 'Intermediate Macroeconomics',
  goal = 'Intermediate Macroeconomics',
  summary = 'Intermediate Macroeconomics develops a model-based and evidence-based understanding of growth, fluctuations, inflation, unemployment, financial markets, monetary and fiscal policy, open-economy dynamics, and crises. Students learn to connect theory to live macroeconomic data and to communicate policy tradeoffs with analytical discipline.',
  data = $imacjson${"slug": "intermediate-macroeconomics", "title": "Intermediate Macroeconomics", "description": "Intermediate Macroeconomics develops a model-based and evidence-based understanding of growth, fluctuations, inflation, unemployment, financial markets, monetary and fiscal policy, open-economy dynamics, and crises. Students learn to connect theory to live macroeconomic data and to communicate policy tradeoffs with analytical discipline.", "topics": [{"id": "8cde26e0-246f-4343-b46d-4ffc7fc9c086", "type": "topic", "title": "Macroeconomic Measurement, Data, and National Income Accounting", "description": "Students learn how macroeconomic aggregates are defined, measured, revised, and interpreted using real data.", "children": [{"id": "b6515618-1778-4b16-b0c7-f71470d4b3c5", "type": "subtopic", "title": "National accounts", "children": [{"id": "41139a17-72ee-4590-a1d3-c68a6c968731", "type": "concept", "title": "GDP by expenditure, income, and value added"}, {"id": "7f35288d-1958-40ea-85f0-3b2bdbc86dd7", "type": "concept", "title": "GNP, NNP, national income, and disposable income"}, {"id": "e713fc85-5d2b-44e5-8df7-06b82e169beb", "type": "concept", "title": "Nominal versus real variables"}], "description": "The point is to know what GDP and income aggregates measure before using them in models."}, {"id": "df9b83b1-ee38-4e25-b7e9-12fb699c9e99", "type": "subtopic", "title": "Labor, prices, and productivity indicators", "children": [{"id": "be6af765-5ce3-4836-bb96-74ac7e620b33", "type": "concept", "title": "Unemployment and labor-force participation"}, {"id": "f49a6279-7f03-4dc9-b34b-99f4ffe44bea", "type": "concept", "title": "CPI, PCE, GDP deflator, and inflation"}, {"id": "a28dba6d-223c-4a07-8db4-f9a098af4daa", "type": "concept", "title": "Productivity and unit labor costs"}], "description": "Students learn the headline indicators used to diagnose macroeconomic conditions."}, {"id": "d2270599-02bd-48bd-afbb-e223edbdc397", "type": "subtopic", "title": "Macroeconomic data practice", "children": [{"id": "98a4c8b0-ca7d-4834-905d-a748fc5ea6b4", "type": "concept", "title": "FRED, BEA, BLS, IMF, and World Bank data"}, {"id": "5a7d1021-6a85-4cd9-b062-edbf15c03ba6", "type": "concept", "title": "Seasonal adjustment and revisions"}, {"id": "e49e6cfc-4d97-45b6-a818-1c7f036d809b", "type": "concept", "title": "Charts, transformations, and growth rates"}], "description": "Intermediate macro uses live data, not only textbook diagrams."}]}, {"id": "f3a32eb0-ea80-4c9e-9739-75b0ee272abd", "type": "topic", "title": "Aggregate Production, Factor Markets, and Long-Run National Income", "description": "This module builds the classical long-run model of output, income, interest rates, and factor payments.", "children": [{"id": "f07a8658-f25e-4b28-8916-34cba9e83ae4", "type": "subtopic", "title": "Production functions", "children": [{"id": "0512432a-81b7-46b1-b85f-9073128fcbfb", "type": "concept", "title": "Cobb-Douglas production"}, {"id": "d3266fb0-1874-48c6-a475-6a5567eb956b", "type": "concept", "title": "Returns to scale"}, {"id": "c008986a-585b-42d9-a477-1c1a16ddc26b", "type": "concept", "title": "Marginal products"}], "description": "Production functions connect labor, capital, technology, and output."}, {"id": "2ac18a31-1485-4ad1-a2fb-34a90f82b7f8", "type": "subtopic", "title": "Factor markets", "children": [{"id": "2c27394d-c498-4337-ade6-becffc007a97", "type": "concept", "title": "Real wages and rental rate of capital"}, {"id": "17a18ddc-631f-4046-91ae-d8d52acf7053", "type": "concept", "title": "Labor and capital income shares"}, {"id": "39bc1342-f368-4b5b-bd42-6ee701e3d10e", "type": "concept", "title": "Distribution and productivity links"}], "description": "Students learn how factor payments and income shares emerge in the long-run model."}, {"id": "94e853b3-0888-4986-a495-adb793ea1d8d", "type": "subtopic", "title": "Saving, investment, and interest rates", "children": [{"id": "71ec110d-346b-4c0d-bec7-1a1473a076b5", "type": "concept", "title": "National saving"}, {"id": "74e7aae2-cb2f-4b5e-a7f5-70da1ffac0b3", "type": "concept", "title": "Investment demand"}, {"id": "b9b0e93a-8af1-49bc-a04c-fdf8b27fd3f9", "type": "concept", "title": "Real interest-rate determination"}], "description": "The long-run loanable-funds model frames how saving finances investment."}]}, {"id": "08fab2ae-cfde-4ee1-a348-f8d66d4d537b", "type": "topic", "title": "Economic Growth I: Solow Model, Capital Accumulation, and Productivity", "description": "Students develop the workhorse model for long-run growth, convergence, and living standards.", "children": [{"id": "65cda0e0-f265-4aa8-8889-57a0e160d9ca", "type": "subtopic", "title": "Solow model mechanics", "children": [{"id": "52346a91-6efe-4858-9f56-a650a738a9d8", "type": "concept", "title": "Capital per worker"}, {"id": "32dfc646-0948-4064-86a0-dfc709f1bd8a", "type": "concept", "title": "Steady state"}, {"id": "3be2636c-855d-4ea7-87eb-c495b0d692d3", "type": "concept", "title": "Golden-rule capital"}], "description": "Students learn how capital accumulation and depreciation shape growth paths."}, {"id": "c4ed7177-1c58-4d5c-a690-6149530d251a", "type": "subtopic", "title": "Technology and productivity", "children": [{"id": "aaf12853-1c39-494a-b37e-d18b4ac1ffa3", "type": "concept", "title": "Total factor productivity"}, {"id": "0a3ac30e-ed6b-4fc6-b8f2-f5bb5a01ed61", "type": "concept", "title": "Labor-augmenting technology"}, {"id": "1c08ae9c-e083-4ace-b0eb-8a9b7fabdd15", "type": "concept", "title": "Growth accounting"}], "description": "Long-run income growth ultimately depends on productivity growth."}, {"id": "68fe9ed2-e879-4ae9-b497-f57864d1b3ad", "type": "subtopic", "title": "Convergence and policy", "children": [{"id": "98afabd6-8122-4d46-91a4-3968615a564d", "type": "concept", "title": "Conditional convergence"}, {"id": "e90be953-2cbf-410b-958c-b4316a237191", "type": "concept", "title": "Population growth"}, {"id": "489f9102-7bd0-4b96-b11b-6d0d6ef98ca0", "type": "concept", "title": "Savings and investment policy"}], "description": "The model helps compare economies and evaluate saving, population, and productivity policies."}]}, {"id": "d79a34c2-039d-4efd-ac40-eb7c7bae0168", "type": "topic", "title": "Economic Growth II: Endogenous Growth, Institutions, and Development", "description": "This topic extends growth analysis to innovation, human capital, institutions, inequality, and cross-country evidence.", "children": [{"id": "d53cc78d-8722-4546-8d29-144297d9d8e9", "type": "subtopic", "title": "Endogenous growth mechanisms", "children": [{"id": "4ea70552-6f34-459e-9dc0-6968f2d9f8a1", "type": "concept", "title": "Knowledge spillovers"}, {"id": "074d871c-bd7f-4960-9241-bf55c33ca89a", "type": "concept", "title": "Human capital"}, {"id": "fd9e5dcb-f69b-48d5-983c-09b2b96e3202", "type": "concept", "title": "R&D and innovation incentives"}], "description": "Students learn how ideas, human capital, and spillovers can sustain growth."}, {"id": "9db0ca57-016b-4130-9ece-d0fd9e28c1fb", "type": "subtopic", "title": "Institutions and development", "children": [{"id": "7422e6f9-81d2-4254-9613-2bc5db6390e8", "type": "concept", "title": "Property rights and governance"}, {"id": "aeed97be-0c83-41fb-9aa4-0778233c5f9a", "type": "concept", "title": "Financial development"}, {"id": "9e960748-80f8-41af-baa5-0649591885e1", "type": "concept", "title": "Political economy and state capacity"}], "description": "Growth depends on more than capital accumulation."}, {"id": "b2392180-0c19-484e-a03b-19f88afcfc46", "type": "subtopic", "title": "Inequality and global evidence", "children": [{"id": "e6891d6e-f703-4470-bcc7-4565b4acf1ae", "type": "concept", "title": "Poverty traps"}, {"id": "020df519-8c99-4c98-bc59-8f0609610ad0", "type": "concept", "title": "Structural transformation"}, {"id": "f069ee66-22c0-438a-9660-35eee78aea9f", "type": "concept", "title": "Inequality, mobility, and inclusive growth"}], "description": "Students interpret growth through cross-country and distributional evidence."}]}, {"id": "569b1263-4fde-45ff-8515-c960b8bb2751", "type": "topic", "title": "Consumption, Saving, Investment, and Intertemporal Choice", "description": "Students learn how households and firms make dynamic decisions that shape aggregate demand and capital formation.", "children": [{"id": "56d0dc43-a3ec-4f3a-a125-f45967edb79f", "type": "subtopic", "title": "Consumption theory", "children": [{"id": "4cfbe8c7-c3b8-45e5-a238-7f682d10ee55", "type": "concept", "title": "Keynesian consumption function"}, {"id": "36f19682-f926-43c3-aab6-43ff90807513", "type": "concept", "title": "Permanent income and life-cycle hypotheses"}, {"id": "1a1702d5-12b2-4ed5-97f2-741892184653", "type": "concept", "title": "Precautionary saving"}], "description": "Consumption depends on income, wealth, expectations, and constraints."}, {"id": "fc6b10d9-f3ad-4fcc-aab6-f01c5d310ca0", "type": "subtopic", "title": "Investment theory", "children": [{"id": "7a0b6dea-ab20-43bd-a6c5-5b89e8555ff0", "type": "concept", "title": "User cost of capital"}, {"id": "59eacd16-12cd-45e8-9752-31651f4e383a", "type": "concept", "title": "Tobin's q"}, {"id": "233e951f-0b79-47fa-a55f-9638f5bd0228", "type": "concept", "title": "Adjustment costs"}], "description": "Firms invest when expected returns justify costs and uncertainty."}, {"id": "72a65566-e196-404c-8aeb-7b54c26d67d9", "type": "subtopic", "title": "Intertemporal choice", "children": [{"id": "6ed8cf8a-93ea-4f53-bf72-fe21c3bbcd19", "type": "concept", "title": "Budget constraints"}, {"id": "a4a57831-f63b-46e1-8a1b-908e51b0520d", "type": "concept", "title": "Euler-equation intuition"}, {"id": "933dc6e1-5ff9-4157-aff9-3079f2496f89", "type": "concept", "title": "Credit constraints and heterogeneity"}], "description": "Students see macro decisions as tradeoffs across time."}]}, {"id": "1321d73f-4deb-4c3a-95e9-8f44e87e73fd", "type": "topic", "title": "Money, Banking, Financial Markets, and the Yield Curve", "description": "This module explains money creation, banking, interest rates, asset prices, and the financial system's macro role.", "children": [{"id": "587a1c15-1793-45d3-8019-0742fa434da0", "type": "subtopic", "title": "Money and banking", "children": [{"id": "858926d3-405b-402d-9315-9dcf1d4119ad", "type": "concept", "title": "Money demand and money supply"}, {"id": "c71f9888-e35d-486a-a40a-29502d9b8863", "type": "concept", "title": "Deposit creation"}, {"id": "fb7e7c9b-7ffc-469c-ae6a-23d19268b462", "type": "concept", "title": "Central bank balance sheets"}], "description": "Money, deposits, and bank balance sheets shape liquidity and credit."}, {"id": "7bfdd9b3-2313-4408-8e46-59191602bd28", "type": "subtopic", "title": "Interest rates and asset markets", "children": [{"id": "60c4f369-9d6c-47d3-8b10-bb494a9943ed", "type": "concept", "title": "Nominal and real rates"}, {"id": "e9092237-1fd1-4221-b108-e80b4bd04d0f", "type": "concept", "title": "Term structure and yield curve"}, {"id": "47f0c23e-ffef-4b9e-9a1d-41115c675b86", "type": "concept", "title": "Risk premia"}], "description": "Interest rates summarize time, risk, policy, and expectations."}, {"id": "cbe15e85-7587-401e-9198-ec9eb0fe14af", "type": "subtopic", "title": "Financial intermediation", "children": [{"id": "b578708b-6fb2-4c65-8d24-01506db8b942", "type": "concept", "title": "Credit channels"}, {"id": "311f3905-180d-4d75-8083-b6ba9d1348a2", "type": "concept", "title": "Leverage and collateral"}, {"id": "c2a7e612-bdfd-4056-9ca1-b71b7ca56711", "type": "concept", "title": "Bank runs and liquidity risk"}], "description": "Finance amplifies or stabilizes macro shocks depending on institutional conditions."}]}, {"id": "b16950ad-696c-4d17-aeb2-da1c611a6b55", "type": "topic", "title": "Short-Run Fluctuations, IS-LM, and Aggregate Demand", "description": "Students learn a core short-run framework for output, interest rates, policy, and demand shocks.", "children": [{"id": "50f5a21d-9e29-4f31-9a41-f1b665dea130", "type": "subtopic", "title": "Goods market and IS curve", "children": [{"id": "1257beb6-d873-4deb-96eb-5446b32289a9", "type": "concept", "title": "Consumption and investment demand"}, {"id": "140a9c67-ddb3-4478-a80d-d049e709b3a9", "type": "concept", "title": "Government purchases and taxes"}, {"id": "495a8616-3bbd-46f6-9ab6-875e15de8bfb", "type": "concept", "title": "Multiplier logic"}], "description": "The IS curve organizes how spending and interest rates determine short-run output."}, {"id": "5dba22ee-fea0-4309-90ce-56bd841ef9fc", "type": "subtopic", "title": "Money market and LM curve", "children": [{"id": "25587d50-c88c-4539-98bf-2cd586888b30", "type": "concept", "title": "Liquidity preference"}, {"id": "4380f4a3-6495-4564-be98-4921739b743f", "type": "concept", "title": "Money demand shifts"}, {"id": "6b91c52d-5bd7-4aba-85cd-610b1d9ceb64", "type": "concept", "title": "Interest-rate targeting"}], "description": "The LM curve links money demand, interest rates, output, and monetary policy."}, {"id": "e411d54b-313c-4f24-851c-2e8604df3621", "type": "subtopic", "title": "Policy and shocks", "children": [{"id": "663fc52c-a0f2-4018-9f38-aca0b5939590", "type": "concept", "title": "Fiscal expansion"}, {"id": "da4387a0-df40-49bc-a90b-9dd740672fec", "type": "concept", "title": "Monetary easing"}, {"id": "75220d16-4fe2-4a11-8714-aa86f00b1b27", "type": "concept", "title": "Crowding out and liquidity traps"}], "description": "IS-LM helps students reason through short-run disturbances and stabilization."}]}, {"id": "af78f18b-074a-4b2c-84b6-2e8f8b95ae2a", "type": "topic", "title": "Aggregate Supply, Labor Markets, Unemployment, and Wage Setting", "description": "This topic links production, labor-market frictions, wage/price behavior, and short-run supply.", "children": [{"id": "c553977e-e501-40b8-b8db-eeb3a3ac70b4", "type": "subtopic", "title": "Aggregate supply", "children": [{"id": "50ecddb5-26e2-4f99-ae89-b7092a04cbdf", "type": "concept", "title": "Short-run versus long-run AS"}, {"id": "2791fa73-5d7b-4a12-b811-66e624bfcc40", "type": "concept", "title": "Sticky wages and prices"}, {"id": "2a18548c-f49c-4e5f-ae5f-9a98ecffa430", "type": "concept", "title": "Supply shocks"}], "description": "Supply-side behavior determines how output and prices respond to demand."}, {"id": "24ee4093-2822-4971-b8ac-90c73438102e", "type": "subtopic", "title": "Labor markets", "children": [{"id": "b04b188c-65cf-4bf1-99ed-e02f8ce8d246", "type": "concept", "title": "Natural rate"}, {"id": "861c630a-fec0-4e0a-9942-2e02d18fcdc2", "type": "concept", "title": "Search and matching intuition"}, {"id": "d0609402-db05-4405-8096-f574a3948124", "type": "concept", "title": "Labor-market participation"}], "description": "Unemployment reflects frictions, institutions, and cyclical conditions."}, {"id": "0fd3a6dc-78f3-4e35-8a5d-c1fdb3ae0165", "type": "subtopic", "title": "Wage and price setting", "children": [{"id": "b0225b6c-4034-4961-a8a4-614566e6e834", "type": "concept", "title": "Nominal rigidity"}, {"id": "1ffa692d-6942-4bf2-9b8a-5623446c3dd8", "type": "concept", "title": "Efficiency wages"}, {"id": "36c36502-491f-4635-a9a4-25b1e6d55d46", "type": "concept", "title": "Markup pricing"}], "description": "Students learn how expectations and bargaining influence macro outcomes."}]}, {"id": "b5a1a7fa-be67-442c-8779-ea9552029a35", "type": "topic", "title": "Inflation, Expectations, and the Phillips Curve", "description": "Students analyze inflation dynamics, expectations, credibility, and the unemployment-inflation tradeoff.", "children": [{"id": "f27ee212-7bbd-4181-a489-f65c63aea6e5", "type": "subtopic", "title": "Inflation dynamics", "children": [{"id": "a8ee235f-705c-41af-b423-6770c877970e", "type": "concept", "title": "Demand-pull and cost-push inflation"}, {"id": "f120ebae-e90f-4dda-a87a-5e8d121bb141", "type": "concept", "title": "Core inflation"}, {"id": "2b16363c-3924-40cd-aecb-fcfb613fd222", "type": "concept", "title": "Inflation persistence"}], "description": "Inflation reflects demand, supply, expectations, and policy credibility."}, {"id": "3785a4d5-88ae-40f7-ae50-8bf5ec29b394", "type": "subtopic", "title": "Expectations", "children": [{"id": "6efb814b-acf7-47fb-962c-58390bb17766", "type": "concept", "title": "Adaptive expectations"}, {"id": "fbc336ae-4dc1-42ed-aa2b-64585ce78d78", "type": "concept", "title": "Rational expectations intuition"}, {"id": "a7108573-5e1e-4367-881a-4fea6bd541f2", "type": "concept", "title": "Anchored versus unanchored expectations"}], "description": "Macroeconomic outcomes depend on what households, firms, and markets expect."}, {"id": "e87612e0-db9f-4485-a60e-aa69729ca80c", "type": "subtopic", "title": "Phillips curve analysis", "children": [{"id": "8ce038c1-ee09-495f-9509-bbe48083f4aa", "type": "concept", "title": "Expectations-augmented Phillips curve"}, {"id": "1568c81b-3bcf-4155-b6ad-0dedd1c409ef", "type": "concept", "title": "NAIRU"}, {"id": "12ecd7f3-70db-4cb6-a559-83350b7ccff9", "type": "concept", "title": "Sacrifice ratio and disinflation"}], "description": "The Phillips curve helps interpret unemployment-inflation tradeoffs and policy choices."}]}, {"id": "ddf89284-58fa-4542-9b72-1521ed1b34ea", "type": "topic", "title": "Monetary Policy, Central Banks, and Policy Rules", "description": "This module develops central-bank tools, monetary transmission, inflation targeting, and unconventional policy.", "children": [{"id": "c2fb016d-ce28-49e2-82f4-0b8aeb5d882c", "type": "subtopic", "title": "Central bank tools", "children": [{"id": "f26ca35c-ca8d-45a3-b1f4-38a6ced3cbe1", "type": "concept", "title": "Policy rates"}, {"id": "7ac8fa49-b5c6-4a2b-8952-3af4fd682293", "type": "concept", "title": "Open-market operations"}, {"id": "4e6037ee-985e-4447-91f9-5b92beeb72fc", "type": "concept", "title": "Reserve systems and balance sheets"}], "description": "Students learn how central banks influence financial conditions and aggregate demand."}, {"id": "00f6a7fc-83cc-4acf-a1dd-562841f49506", "type": "subtopic", "title": "Monetary transmission", "children": [{"id": "afd4b27b-0df4-49ac-a126-5039d7dcf005", "type": "concept", "title": "Interest-rate channel"}, {"id": "96c2fe93-9c1d-4aff-88b8-c804d66478df", "type": "concept", "title": "Credit channel"}, {"id": "78c334f8-83ed-4f1a-88dc-bfe36a6e7e6f", "type": "concept", "title": "Exchange-rate and asset-price channels"}], "description": "Policy works through multiple channels and with lags."}, {"id": "f1ed8d55-8358-49d8-8e9a-38e27ddfb7e3", "type": "subtopic", "title": "Policy frameworks", "children": [{"id": "1f05adc0-a459-4e2e-81c2-b350a2679640", "type": "concept", "title": "Taylor rule"}, {"id": "51866796-bd0b-4164-a03b-f7a5d175e2e3", "type": "concept", "title": "Inflation targeting"}, {"id": "2053b4d1-a18f-4c35-899e-784535a0d777", "type": "concept", "title": "Quantitative easing and forward guidance"}], "description": "The course compares policy rules, discretion, and credibility."}]}, {"id": "3df5d39d-98a0-49f3-88e2-f497569fbbdc", "type": "topic", "title": "Fiscal Policy, Deficits, Government Debt, and Sustainability", "description": "Students study stabilization, multipliers, intertemporal budgets, debt dynamics, and fiscal credibility.", "children": [{"id": "134270cd-3cf2-40d5-a1a7-d5ef1270ca5c", "type": "subtopic", "title": "Fiscal stabilization", "children": [{"id": "c8dae0a0-8886-4302-a6d4-d1fe9a73780d", "type": "concept", "title": "Automatic stabilizers"}, {"id": "f2481b0a-1613-4bee-9208-cd6ebfe5abcf", "type": "concept", "title": "Discretionary stimulus"}, {"id": "d1e686f1-279b-435c-bee1-262aa9561c4b", "type": "concept", "title": "Fiscal multipliers"}], "description": "Government spending and taxes can stabilize or destabilize aggregate demand."}, {"id": "8eecf6ee-6c52-4568-9e3e-a806793f00f8", "type": "subtopic", "title": "Government budget constraint", "children": [{"id": "4f24c080-a03e-4f2e-979c-390b04fae8e8", "type": "concept", "title": "Primary deficits"}, {"id": "ff00e76c-ae43-41cc-ad90-4599f32dc896", "type": "concept", "title": "Debt-to-GDP dynamics"}, {"id": "805c8bbb-7ea8-43fb-9fde-18a8bc37c9ab", "type": "concept", "title": "Interest-growth differential"}], "description": "Debt dynamics link current policy to future taxes, inflation, and credibility."}, {"id": "77a8e442-1f20-449f-a8ea-5990978d0e49", "type": "subtopic", "title": "Fiscal sustainability and distribution", "children": [{"id": "98e14eec-2539-477e-81c8-7c891cae1161", "type": "concept", "title": "Ricardian equivalence debate"}, {"id": "4a7d118c-f858-4457-beaa-731de1335b39", "type": "concept", "title": "Debt crises and fiscal space"}, {"id": "185e66bd-6f25-47d6-a354-014c370cfd02", "type": "concept", "title": "Transfers, public investment, and inequality"}], "description": "Fiscal policy has intergenerational and distributional consequences."}]}, {"id": "88fdcaac-7dca-49e0-9fe1-ecb7b6b837c0", "type": "topic", "title": "Open-Economy Macroeconomics, Exchange Rates, and Capital Flows", "description": "This topic connects domestic macro models to trade balances, exchange rates, global finance, and country risk.", "children": [{"id": "1826f3d3-8e40-4eb3-83af-c6a71bc39002", "type": "subtopic", "title": "Balance of payments", "children": [{"id": "24aa73b9-8341-45e0-b180-d876da0643ad", "type": "concept", "title": "Current account"}, {"id": "80164f66-4fe6-46ae-8f55-e887479a1253", "type": "concept", "title": "Financial account"}, {"id": "503059f2-6448-40e0-9d23-ed3f6391e099", "type": "concept", "title": "Net international investment position"}], "description": "Open economies track trade, income, transfers, and capital flows."}, {"id": "10090c2b-fb62-40ab-8e0f-6f04004b62f0", "type": "subtopic", "title": "Exchange rates", "children": [{"id": "f803eb03-0cd6-4e3a-a1fa-b22c1219b1f4", "type": "concept", "title": "Nominal and real exchange rates"}, {"id": "6ecbc88a-f76f-442d-a280-72663b335b46", "type": "concept", "title": "Purchasing power parity"}, {"id": "743c3cfa-0150-44e6-9e19-eb07633abd68", "type": "concept", "title": "Interest parity"}], "description": 